/*          http://www.opensource.org                              */
/*          http://www.opensource.org/licenses/gpl-license.html    */
/*                                                                 */
/* =============================================================== */
/*  History:                                                       */
/*                                                                 */
/*  Datum       Name          Änderung                             */
/*  ----------  ------------  -----------------------------------  */
/*                                                                 */
/* =============================================================== */
/* >>PRE-COMPILER<<                                                */
/*                                                                 */
/*   >>CRTCMD<< CRTCMD       CMD(&LI/&OB) +                        */
/*                           SRCFILE(&SL/&SF) +                    */
/*                           SRCMBR(&SM);                          */
/*                                                                 */
/*   >>COMPILE<<                                                   */
/*     >>PARM<< PGM(&LI/ENDDBGR);                                  */
/*     >>PARM<< MODE(*DEBUG);                                      */
/*     >>PARM<< ALLOW(*ALL);                                       */
/*     >>PARM<< MAXPOS(*NOMAX);                                    */
/*     >>PARM<< PMTFILE(QDEVELOP/QCPFPMT);                         */
/*     >>PARM<< HLPSCHIDX(*NONE);                                  */
/*     >>PARM<< HLPPNLGRP(*LIBL/ENDDBGP);                          */
/*     >>PARM<< HLPID(ENDDBG);                                     */
/*   >>END-COMPILE<<                                               */
/*                                                                 */
/*   >>EXECUTE<<                                                   */
/*                                                                 */
/* >>END-PRE-COMPILER<<                                            */
/* =============================================================== */
             CMD        PROMPT('End Debug Mode')

**free
